/**
 * The capture brain package (src/brain/capture/) is generated by tools/brain/build_brain.py and
 * committed as-is. These checks catch a partial or mismatched copy: the module, its version file and
 * its embedded difficulty levels must agree.
 */

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { createBrain, createFairView, DIFFICULTY, BRAIN_VERSION } from './capture/capture_brain.js';

const dir = join(__dirname, 'capture');

describe('capture brain package', () => {
  it('exports the documented API', () => {
    expect(typeof createBrain).toBe('function');
    expect(typeof createFairView).toBe('function');
  });

  it('matches its BRAIN_VERSION.json', () => {
    const file = JSON.parse(readFileSync(join(dir, 'BRAIN_VERSION.json'), 'utf8'));
    expect(BRAIN_VERSION).toEqual(file);
  });

  it('has the three difficulty levels', () => {
    expect(DIFFICULTY).toEqual({
      easy: { delayTicks: 25, thinkEvery: 3 },
      normal: { delayTicks: 12, thinkEvery: 2 },
      hard: { delayTicks: 5, thinkEvery: 1 },
    });
  });

  it('ships the same build as a classic script', () => {
    const iife = readFileSync(join(dir, 'capture_brain.iife.js'), 'utf8');
    expect(iife).toContain('CaptureBrain');
    expect(iife).toContain(BRAIN_VERSION.hook_md5);
  });
});
